import unittest
from candidate import below_threshold

class TestBelowThreshold(unittest.TestCase):
    def test_normal_all_below(self):
        self.assertTrue(below_threshold([1, 2, 3, 4], 10))

    def test_false_when_equal(self):
        self.assertFalse(below_threshold([1, 2, 3], 3))

    def test_false_when_above(self):
        self.assertFalse(below_threshold([5, 6, 7], 6))

    def test_empty_list_true(self):
        self.assertTrue(below_threshold([], 1))

    def test_boundary_equal_element(self):
        self.assertFalse(below_threshold([0, -1, 2], 2))

    def test_negative_numbers_true(self):
        self.assertTrue(below_threshold([-10, -5, -1], 0))

    def test_negative_numbers_false(self):
        self.assertFalse(below_threshold([-10, -5, -1], -5))

    def test_float_numbers_true(self):
        self.assertTrue(below_threshold([1.5, 2.5, 3.5], 5))

    def test_generator_input(self):
        self.assertTrue(below_threshold((x for x in range(5)), 10))

    def test_tuple_input(self):
        self.assertTrue(below_threshold((1, 2, 3), 5))

    def test_set_input(self):
        self.assertTrue(below_threshold({1, 2, 3}, 5))

    def test_invalid_type_l_not_iterable(self):
        with self.assertRaises(TypeError):
            below_threshold(123, 10)

    def test_invalid_type_l_contains_none(self):
        with self.assertRaises(TypeError):
            below_threshold([1, None, 3], 5)

    def test_invalid_type_t_none(self):
        with self.assertRaises(TypeError):
            below_threshold([1, 2, 3], None)

    def test_invalid_type_t_string(self):
        with self.assertRaises(TypeError):
            below_threshold([1, 2, 3], 'five')

    def test_l_is_none(self):
        with self.assertRaises(TypeError):
            below_threshold(None, 5)

    def test_non_numeric_in_list(self):
        with self.assertRaises(TypeError):
            below_threshold([1, 'a', 3], 5)

    def test_complex_numbers(self):
        with self.assertRaises(TypeError):
            below_threshold([1, 2+3j], 5)

if __name__ == '__main__':
    unittest.main()
